#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct MultimodalIngestionReceipt{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub bundle_id:String,pub consumer:String,pub disposition:String,pub required_modality_order:Vec<String>,pub object_order:Vec<String>,pub harmonized_order:Vec<String>,pub missing_order:Vec<String>,pub stale_order:Vec<String>,pub blocked_order:Vec<String>,pub unknown_order:Vec<String>,pub omitted_order:Vec<String>,pub semantic_loss_order:Vec<String>,pub objects:Vec<HarmonizedObject>,pub omissions:Vec<String>,pub uncertainty:Vec<String>,pub negative_evidence:Vec<String>,pub replay_identity:ContentHash,pub ingestion_digest:ContentHash,pub effect_receipts:Vec<String>,pub artifact:serde_json::Value,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
